// Never trust incoming data, even from our own backend: check it before using it.
const event = $input.first().json.body || {};
const d = event.data || {};
const text = (t, max) => String(t ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
if (event.type !== 'followup.approved') throw new Error('Unexpected event type - ' + text(event.type, 40));
if (!/^FU-[A-Za-z0-9-]{1,40}$/.test(d.followUpId || '')) throw new Error('The event has no valid followUpId');
if (!/^LD-[A-Za-z0-9-]{1,40}$/.test(d.leadId || '')) throw new Error('The event has no valid leadId');
// Stage 6 decision D2A: delivery is SIMULATED. Refuse anything else.
if (d.delivery !== 'simulated') throw new Error('Only SIMULATED delivery is allowed in Stage 6');

const message = 'SIMULATED email for follow-up ' + d.followUpId + ' ("' + text(d.subject, 80) + '"): NOT sent to the customer, no real email left the system.';
return [{ json: { followUpId: d.followUpId, leadId: d.leadId, message } }];

// Did the backend accept it? 2xx → continue with its answer (the JSON body).
// Anything else FAILS this run (→ WF4 escalates), labelled so a person knows what to do:
//   TEMPORARY (408, 429, 5xx): the backend had a problem; trying again later can work
//   PERMANENT (other 4xx):     retrying can never fix it, so it is NOT retried
// "No answer at all" never gets here: the HTTP node already retried that 3 times.
const r = $input.first().json;
const s = r.statusCode;
if (s >= 200 && s < 300) return [{ json: r.body ?? {} }];
const code = (r.body && r.body.error && r.body.error.code) || 'no error code';
const temporary = s === 408 || s === 429 || (s >= 500 && s <= 599);
throw new Error((temporary ? 'TEMPORARY' : 'PERMANENT') + ' backend answer to "Claim it" - HTTP ' + s + ' ' + code + (temporary ? '' : ' (not retried, retrying cannot fix it)'));

const answer = $input.first().json;
// claimed: true  → this run owns the follow-up: deliver it.
// claimed: false → another run already has it ("sending" or "sent"): a duplicate event. Stop quietly.
// (draft / rejected never get here: the claim answers 409, and "Check: Claim it" fails the run.)
if (answer.claimed !== true) return [];
